  { id: 16001, genre: "敬語・丁寧表現", type: "choice", stem: "相手の会社を敬って呼ぶ際の適切な言葉はどれ？", options: ["貴社", "弊社", "当社", "自社"], answer: "貴社" },
  { id: 16002, genre: "敬語・丁寧表現", type: "choice", stem: "自分の会社をへりくだって呼ぶ際の適切な言葉はどれ？", options: ["弊社", "貴社", "御社", "御中"], answer: "弊社" },
  { id: 16003, genre: "敬語・丁寧表現", type: "choice", stem: "「行く」の尊敬語として適切なものはどれ？", options: ["いらっしゃる", "参る", "伺う", "まいる"], answer: "いらっしゃる" },
  { id: 16004, genre: "敬語・丁寧表現", type: "choice", stem: "「食べる」の謙譲語として適切なものはどれ？", options: ["いただく", "召し上がる", "食べられる", "お食べになる"], answer: "いただく" },
  { id: 16005, genre: "敬語・丁寧表現", type: "choice", stem: "「言う」の謙譲語として適切なものはどれ？", options: ["申す", "おっしゃる", "言われる", "宣う"], answer: "申す" },
  { id: 16006, genre: "敬語・丁寧表現", type: "choice", stem: "「見る」の尊敬語として適切なものはどれ？", options: ["ご覧になる", "拝見する", "見られる", "ご覧いただく"], answer: "ご覧になる" },
  { id: 16007, genre: "敬語・丁寧表現", type: "choice", stem: "「見る」の謙譲語として適切なものはどれ？", options: ["拝見する", "ご覧になる", "拝読する", "拝聴する"], answer: "拝見する" },
  { id: 16008, genre: "敬語・丁寧表現", type: "choice", stem: "「聞く・訪問する」の謙譲語として適切なものはどれ？", options: ["伺う", "お聞きになる", "いらっしゃる", "お尋ねになる"], answer: "伺う" },
  { id: 16009, genre: "敬語・丁寧表現", type: "choice", stem: "「知っている」の謙譲語・丁寧な表現はどれ？", options: ["存じ上げている", "ご存知だ", "知っていらっしゃる", "ご存知である"], answer: "存じ上げている" },
  { id: 16010, genre: "敬語・丁寧表現", type: "choice", stem: "「知っている」の尊敬語はどれ？", options: ["ご存知だ", "存じ上げている", "存じる", "知っておく"], answer: "ご存知だ" },
  { id: 16011, genre: "敬語・丁寧表現", type: "choice", stem: "「与える・やる」の謙譲語はどれ？", options: ["差し上げる", "下さる", "お与えになる", "進呈される"], answer: "差し上げる" },
  { id: 16012, genre: "敬語・丁寧表現", type: "choice", stem: "「もらう」の謙譲語はどれ？", options: ["頂戴する・いただく", "くださる", "お受けになる", "お納めになる"], answer: "頂戴する・いただく" },
  { id: 16013, genre: "敬語・丁寧表現", type: "choice", stem: "「くれる」の尊敬語はどれ？", options: ["くださる", "いただく", "差し上げる", "賜る"], answer: "くださる" },
  { id: 16014, genre: "敬語・丁寧表現", type: "choice", stem: "「会う」の謙譲語はどれ？", options: ["お目にかかる", "お会いになる", "会われる", "面会される"], answer: "お目にかかる" },
  { id: 16015, genre: "敬語・丁寧表現", type: "choice", stem: "「考える」の謙譲語はどれ？", options: ["拝察する", "お考えになる", "思われる", "ご一考なさる"], answer: "拝察する" },
  { id: 16016, genre: "敬語・丁寧表現", type: "choice", stem: "「座る」の尊敬語として適切なものはどれ？", options: ["お掛けになる", "座られる", "ご着席いただく", "お座りする"], answer: "お掛けになる" },
  { id: 16017, genre: "敬語・丁寧表現", type: "choice", stem: "二重敬語になってしまっている誤った表現はどれ？", options: ["社長がおっしゃられました", "社長がおっしゃいました", "社長が言われました", "社長がお話になりました"], answer: "社長がおっしゃられました" },
  { id: 16018, genre: "敬語・丁寧表現", type: "choice", stem: "社外の人に対して自分の上司（山田部長）を話す際の正しい言い方は？", options: ["部長の山田はただいま席を外しております", "山田部長様は席を外されています", "山田部長はお出かけになられました", "部長の山田様は外出中です"], answer: "部長の山田はただいま席を外しております" },
  { id: 16019, genre: "敬語・丁寧表現", type: "choice", stem: "電話口で相手の名前を確認する際の丁寧な表現はどれ？", options: ["恐れ入りますが、お名前を伺ってもよろしいでしょうか", "どちら様でしょうか", "お名前は何とおっしゃいますか", "名前を教えてください"], answer: "恐れ入りますが、お名前を伺ってもよろしいでしょうか" },
  { id: 16020, genre: "敬語・丁寧表現", type: "choice", stem: "「理解して引き受ける」ことを上司や取引先に使う際の適切な敬語表現は？", options: ["かしこまりました / 承知いたしました", "了解いたしました", "りょ", "分かりました"], answer: "かしこまりました / 承知いたしました" },
  { id: 16021, genre: "敬語・丁寧表現", type: "choice", stem: "「ご苦労様です」の使い方として正しい知識はどれ？", options: ["目上の人が目下の人に対して使う言葉（目上に使うのは不可）", "目上の人に対して使う感謝の敬語", "誰にでも使える丁寧な挨拶", "語尾に「です」がついているので敬語"], answer: "目上の人が目下の人に対して使う言葉（目上に使うのは不可）" },
  { id: 16022, genre: "敬語・丁寧表現", type: "choice", stem: "「お世話様です」の性質として正しいものはどれ？", options: ["ご苦労様と同様に目上の人への使用は避けるのが無難", "最高の敬意を表すビジネス用語", "手紙でのみ使える言葉", "目上の人だけに使う言葉"], answer: "ご苦労様と同様に目上の人への使用は避けるのが無難" },
  { id: 16023, genre: "敬語・丁寧表現", type: "choice", stem: "「お体をご自愛ください」という文の注意点は？", options: ["自愛に「体を大切にする」意味が含まれるため「お体」は重複", "間違いではないので積極的に使うべき", "「ご自愛」ではなく「ご慈愛」と書く", "敬語として失礼にあたる"], answer: "自愛に「体を大切にする」意味が含まれるため「お体」は重複" },
  { id: 16024, genre: "敬語・丁寧表現", type: "choice", stem: "手紙の宛名で、会社や部署などの団体宛につける敬称はどれ？", options: ["御中", "様", "殿", "各位"], answer: "御中" },
  { id: 16025, genre: "敬語・丁寧表現", type: "choice", stem: "手紙の宛名で、大勢の人（関係者全員）に送る際につける敬称はどれ？", options: ["各位", "御中", "様方", "殿"], answer: "各位" },
  { id: 16026, genre: "敬語・丁寧表現", type: "choice", stem: "「お客様がお越しになられました」の誤りはどれ？", options: ["「お越しになる」に「られ」がついた二重敬語", "「お客様」という表現", "「お越し」という言葉", "誤りはない"], answer: "「お越しになる」に「られ」がついた二重敬語" },
  { id: 16027, genre: "敬語・丁寧表現", type: "choice", stem: "「拝読する」の意味はどれ？", options: ["「読む」の謙譲語（つつしんで読むこと）", "「読む」の尊敬語", "「書く」の謙譲語", "「調べる」の丁寧語"], answer: "「読む」の謙譲語（つつしんで読むこと）" },
  { id: 16028, genre: "敬語・丁寧表現", type: "choice", stem: "「拝聴する」の意味はどれ？", options: ["「聞く」の謙譲語（つつしんで聞くこと）", "「聞く」の尊敬語", "「話す」の謙譲語", "「歌う」の丁寧語"], answer: "「聞く」の謙譲語（つつしんで聞くこと）" },
  { id: 16029, genre: "敬語・丁寧表現", type: "choice", stem: "「お借りする」のより丁寧な謙譲表現として正しいものはどれ？", options: ["拝借する", "お借りになられる", "お借りいただく", "ご借用される"], answer: "拝借する" },
  { id: 16030, genre: "敬語・丁寧表現", type: "choice", stem: "「伝える」の謙譲語として適切なものはどれ？", options: ["申し伝える", "お伝えになられる", "伝言される", "お伝えいただく"], answer: "申し伝える" }
